import {
  PHI_OVERVIEW_BFF_BEER_EVOLUTION_BREAKDOWN_KEY,
  PHI_OVERVIEW_BFF_PHI_PERFORMANCE_KEY,
  PHI_OVERVIEW_BFF_TOTAL_PHI_KEY,
} from '../../../constants';
import type { PhiOverviewBffResponse } from '../../../types';
import { portfolioHealthBeerEvolutionBreakdownMock } from './portfolioHealthBeerEvolutionBreakdown.mock';
import { portfolioHealthPhiPerformanceMock } from './portfolioHealthPhiPerformance.mock';
import { portfolioHealthTotalPhiMock } from './portfolioHealthTotalPhi.mock';

export const portfolioHealthIndexOverviewMock: PhiOverviewBffResponse = {
  [PHI_OVERVIEW_BFF_TOTAL_PHI_KEY]: portfolioHealthTotalPhiMock,
  [PHI_OVERVIEW_BFF_PHI_PERFORMANCE_KEY]: portfolioHealthPhiPerformanceMock,
  [PHI_OVERVIEW_BFF_BEER_EVOLUTION_BREAKDOWN_KEY]:
    portfolioHealthBeerEvolutionBreakdownMock,
};

export { portfolioHealthBeerEvolutionBreakdownMock } from './portfolioHealthBeerEvolutionBreakdown.mock';
export { portfolioHealthPhiPerformanceMock } from './portfolioHealthPhiPerformance.mock';
export { portfolioHealthTotalPhiMock } from './portfolioHealthTotalPhi.mock';
